def grad(ex,vs):return vec([s.diff(ex,vv) for vv in vs])
def gv(ex,vs,pt):return grad(ex,vs).subs(dict(zip(vs,pt)))
def vf(v,label):return [f(label+' · '+str(j+1),q) if s.sympify(q).free_symbols else n(label+' · '+str(j+1),q,tol=abs(float(q))*1e-8 if q!=0 else 1e-10) for j,q in enumerate(v)]
def dd(ex,vs,pt,d):return s.simplify(gv(ex,vs,pt).dot(unit(vec(d))))
